#include "consumer_consumer.h"

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

void consumer_consumer_initialize(void);
void consumer_consumer_notify(microkit_channel channel);
void consumer_consumer_timeTriggered(void);

volatile sb_queue_bool_1_t *healthy_queue_1;
sb_queue_bool_1_Recv_t healthy_recv_queue;
volatile sb_queue_int32_t_1_t *echo_queue_1;
sb_queue_int32_t_1_Recv_t echo_recv_queue;
volatile sb_queue_bool_1_t *alert_result_queue_1;
sb_queue_bool_1_Recv_t alert_result_recv_queue;
volatile sb_queue_uint8_t_1_t *ack_queue_1;
sb_queue_uint8_t_1_Recv_t ack_recv_queue;

#define PORT_FROM_MON 0

bool last_healthy_payload;

bool get_healthy(bool *data) {
  sb_event_counter_t numDropped;
  bool fresh_data;
  bool isFresh = sb_queue_bool_1_dequeue((sb_queue_bool_1_Recv_t *) &healthy_recv_queue, &numDropped, &fresh_data);
  if (isFresh) {
    last_healthy_payload = fresh_data;
  }
  *data = last_healthy_payload;
  return isFresh;
}

uintmax_t get_healthy_num_invalid(void) {
  return sb_queue_bool_1_numInvalid((sb_queue_bool_1_Recv_t *) &healthy_recv_queue);
}

bool echo_is_empty(void) {
  return sb_queue_int32_t_1_is_empty(&echo_recv_queue);
}

bool get_echo_poll(sb_event_counter_t *numDropped, int32_t *data) {
  return sb_queue_int32_t_1_dequeue((sb_queue_int32_t_1_Recv_t *) &echo_recv_queue, numDropped, data);
}

bool get_echo(int32_t *data) {
  sb_event_counter_t numDropped;
  return get_echo_poll (&numDropped, data);
}

uintmax_t get_echo_num_invalid(void) {
  return sb_queue_int32_t_1_numInvalid((sb_queue_int32_t_1_Recv_t *) &echo_recv_queue);
}

bool alert_result_is_empty(void) {
  return sb_queue_bool_1_is_empty(&alert_result_recv_queue);
}

bool get_alert_result_poll(sb_event_counter_t *numDropped, bool *data) {
  return sb_queue_bool_1_dequeue((sb_queue_bool_1_Recv_t *) &alert_result_recv_queue, numDropped, data);
}

bool get_alert_result(bool *data) {
  sb_event_counter_t numDropped;
  return get_alert_result_poll (&numDropped, data);
}

uintmax_t get_alert_result_num_invalid(void) {
  return sb_queue_bool_1_numInvalid((sb_queue_bool_1_Recv_t *) &alert_result_recv_queue);
}

bool ack_is_empty(void) {
  return sb_queue_uint8_t_1_is_empty(&ack_recv_queue);
}

bool get_ack_poll(sb_event_counter_t *numDropped) {
  uint8_t eventPortPayload;
  uint8_t *data = &eventPortPayload;
  return sb_queue_uint8_t_1_dequeue((sb_queue_uint8_t_1_Recv_t *) &ack_recv_queue, numDropped, data);
}

bool get_ack() {
  sb_event_counter_t numDropped;
  return get_ack_poll (&numDropped);
}

void init(void) {
  printf("%s | INIT!\n", microkit_name);

  sb_queue_bool_1_Recv_init(&healthy_recv_queue, (sb_queue_bool_1_t *) healthy_queue_1);

  sb_queue_int32_t_1_Recv_init(&echo_recv_queue, (sb_queue_int32_t_1_t *) echo_queue_1);

  sb_queue_bool_1_Recv_init(&alert_result_recv_queue, (sb_queue_bool_1_t *) alert_result_queue_1);

  sb_queue_uint8_t_1_Recv_init(&ack_recv_queue, (sb_queue_uint8_t_1_t *) ack_queue_1);

  consumer_consumer_initialize();

  microkit_notify(PORT_FROM_MON);
}

void notified(microkit_channel channel) {
  switch (channel) {
    case PORT_FROM_MON:
      consumer_consumer_timeTriggered();
      // Report that this dispatch has finished.  The _MON wrapper forwards it to
      // the scheduler.  The default scheduler ignores runtime signals from
      // partitions -- the schedule is static and each partition runs for its full
      // allotted time -- so this is inert there; the test scheduler uses it as the
      // slot-complete event, which is what lets it step as fast as threads run
      // rather than waiting out each slot's wall-clock budget.
      microkit_notify(PORT_FROM_MON);
      break;
    default:
      consumer_consumer_notify(channel);
  }
}
